#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# Run through Claude Code's `!`, stdin is not a terminal: the first question would
# read nothing and the wizard would stop there, with the browser already open.
[[ -t 0 ]] || { echo "Ce wizard attend tes réponses : lance-le dans un terminal, pas avec « ! »." >&2; exit 1; }
# `s3_check` signs its requests with the repository's own `aws4fetch`.
cd "$(dirname "$0")/.."

# Every value here is production's, and `.env` is `pnpm dev`'s: nothing is read
# from it as a default, and nothing is written to it. The values go to Vercel's
# Production environment alone — see
# `docs/adr/0092-images-and-sounds-live-in-a-private-bucket.md`.
ENV_FILE="$(mktemp -u)"
WRITTEN_VERCEL=()

# set_vercel_env NAME VALUE writes NAME into the Production environment of the
# Vercel project this checkout is linked to, over any value already there.
set_vercel_env() {
  local name="$1" value="$2"
  vercel env rm "$name" production --yes >/dev/null 2>&1 || true
  if printf '%s' "$value" | vercel env add "$name" production >/dev/null 2>&1; then
    WRITTEN_VERCEL+=("$name")
    printf '  %s✓ set%s %s dans Vercel (Production)\n' "$GREEN" "$RESET" "$name"
  else
    SKIPPED+=("Vercel $name (vercel env add $name production)")
    warn "$name n'a pas pu être écrit dans Vercel : pose-le à la main"
  fi
}

# s3_check METHOD URL prints the status the bucket answers a request signed with
# the token, or nothing when the request could not be made at all.
s3_check() {
  NUXT_MEDIA_ACCESS_KEY_ID="$NUXT_MEDIA_ACCESS_KEY_ID" \
  NUXT_MEDIA_SECRET_ACCESS_KEY="$NUXT_MEDIA_SECRET_ACCESS_KEY" \
  node --input-type=module -e "
    import { AwsClient } from 'aws4fetch'
    const client = new AwsClient({
      accessKeyId: process.env.NUXT_MEDIA_ACCESS_KEY_ID,
      secretAccessKey: process.env.NUXT_MEDIA_SECRET_ACCESS_KEY,
      service: 's3',
      region: 'auto',
    })
    const answered = await client.fetch(process.argv[2], { method: process.argv[1] })
    console.log(answered.status)
  " "$1" "$2" 2>/dev/null || true
}

TOTAL_STAGES=6

banner "Le bucket R2 des Images et des Sons"

stage "Compte Cloudflare et moyen de paiement"
say "Les Images et les Sons vivent dans un bucket Cloudflare R2, qui ne s'active pas"
say "sans moyen de paiement, même pour rester dans son palier gratuit."
open_url "https://dash.cloudflare.com/sign-up"
step "Crée le compte, ou connecte-toi à celui qui existe déjà."
step "Manage Account → Billing → Payment info : ajoute une carte (une prépayée peut être refusée)."
step "Colonne de gauche, R2 object storage : suis le parcours d'abonnement à R2."
note "Le palier gratuit : 10 Go stockés, un million d'écritures et dix de lectures par mois."
pause "Entrée une fois R2 activé sur le compte."

stage "Le bucket, en juridiction eu"
open_url "https://dash.cloudflare.com/?to=/:account/r2/overview"
step "R2 object storage → Overview → Create bucket."
step "Nom : frameline-media, ou un autre que tu donneras ci-dessous."
step "Location → Specify jurisdiction → eu (European Union). Elle ne changera plus."
step "Create bucket."
ask NUXT_MEDIA_BUCKET "Nom du bucket :"
step "De retour sur Overview, copie l'Account ID (Account Details, à droite)."
ask CF_ACCOUNT_ID "Account ID :"
NUXT_MEDIA_ENDPOINT="https://${CF_ACCOUNT_ID}.eu.r2.cloudflarestorage.com"
note "Endpoint : $NUXT_MEDIA_ENDPOINT, le domaine S3 de la juridiction eu,"
note "le seul où R2 répond à une adresse signée."
pause "Entrée pour créer le jeton du bucket."

stage "Un jeton API limité au bucket"
open_url "https://dash.cloudflare.com/?to=/:account/r2/api-tokens"
step "R2 object storage → Overview → Account Details → API Tokens : Manage."
step "Create Account API token, nommé frameline-media."
step "Permissions : Object Read & Write."
step "Specify bucket(s) → Apply to specific buckets only → $NUXT_MEDIA_BUCKET."
step "TTL : Forever. Puis Create Account API token."
step "Copie l'Access Key ID et le Secret Access Key : le second ne se revoit plus."
ask NUXT_MEDIA_ACCESS_KEY_ID "Access Key ID :"
ask_secret NUXT_MEDIA_SECRET_ACCESS_KEY "Secret Access Key :"
listed=$(s3_check GET "$NUXT_MEDIA_ENDPOINT/$NUXT_MEDIA_BUCKET?list-type=2&max-keys=1")
if [[ "$listed" == 200 ]]; then
  printf '  %s✓ le jeton lit le bucket%s\n' "$GREEN" "$RESET"
else
  warn "le bucket a répondu « ${listed:-rien} » au jeton : revois le nom, la juridiction et les clés."
  confirm "Continuer quand même ?" || exit 1
fi
pause "Entrée pour poser la règle CORS."

stage "La règle CORS"
say "GET et HEAD depuis toute origine : l'adresse signée est la permission, et une"
say "Lecture va chercher ses Sons par fetch, qui en a besoin. Un jeton limité au"
say "bucket ne peut pas poser cette règle, d'où le tableau de bord."
open_url "https://dash.cloudflare.com/?to=/:account/r2/overview"
step "Ouvre le bucket $NUXT_MEDIA_BUCKET → Settings → CORS Policy → Add CORS policy."
step "Onglet JSON : colle exactement ceci, puis Save."
printf '\n    %s\n\n' '[{ "AllowedOrigins": ["*"], "AllowedMethods": ["GET", "HEAD"], "MaxAgeSeconds": 3600 }]'
note "La règle met jusqu'à trente secondes à s'appliquer."
pause "Entrée une fois la règle enregistrée."

stage "L'alerte de budget"
say "Au-delà du gratuit, R2 facture sans rien bloquer, et rien ne plafonne la dépense."
say "L'alerte est un courriel, le lendemain du dépassement : mets-la au plus bas."
open_url "https://dash.cloudflare.com/?to=/:account/billing/billable-usage"
step "Manage Account → Billing → Billable Usage → Create budget alert."
step "Alert name : R2 Frameline. Budget threshold (USD) : 0.01, le plus bas accepté."
step "Email recipients : ton adresse. Save."
note "Cloudflare en pose une d'office à 10 \$ ; celle-ci part bien avant."
pause "Entrée une fois l'alerte enregistrée."

stage "L'environnement de production Vercel"
say "Les identifiants du bucket et le secret du cron vont dans l'environnement"
say "Production de Vercel, et nulle part ailleurs : ni .env, ni GitHub."
if ! command -v vercel >/dev/null 2>&1 || ! vercel whoami >/dev/null 2>&1; then
  warn "la CLI vercel manque ou n'est pas connectée : npm i -g vercel, vercel login, vercel link."
  pause "Entrée une fois la CLI connectée et ce dépôt lié au projet."
fi
CRON_SECRET=$(openssl rand -hex 32)
note "CRON_SECRET vient d'être tiré au hasard : Vercel l'envoie au balayage quotidien."
if confirm "Écrire les cinq valeurs dans Vercel (Production), par-dessus celles qui y sont ?"; then
  set_vercel_env NUXT_MEDIA_ENDPOINT "$NUXT_MEDIA_ENDPOINT"
  set_vercel_env NUXT_MEDIA_BUCKET "$NUXT_MEDIA_BUCKET"
  set_vercel_env NUXT_MEDIA_ACCESS_KEY_ID "$NUXT_MEDIA_ACCESS_KEY_ID"
  set_vercel_env NUXT_MEDIA_SECRET_ACCESS_KEY "$NUXT_MEDIA_SECRET_ACCESS_KEY"
  set_vercel_env CRON_SECRET "$CRON_SECRET"
else
  SKIPPED+=("Vercel : NUXT_MEDIA_* et CRON_SECRET (Settings → Environment Variables → Production)")
fi
note "Elles prennent effet au prochain déploiement de production, donc à la prochaine promotion."
pause "Entrée pour finir."

finish
(( ${#WRITTEN_VERCEL[@]} )) && note "écrit dans Vercel (Production) : ${WRITTEN_VERCEL[*]}"
printf '\n'
}

run_wizard "$@"; exit
